def decode_preview(data, extension):
    with contextlib.ExitStack() as stack:
        def pipe():
            reader, writer = os.pipe()
            return (stack.enter_context(os.fdopen(reader, 'rb', buffering=0)),
                    stack.enter_context(os.fdopen(writer, 'wb', buffering=0)))
        source, feed = pipe()
        output, emit = pipe()
        unused, errors = pipe()
        def send():
            try:
                with feed:
                    chunk = memoryview(data)
                    while chunk:
                        chunk = chunk[feed.write(chunk):]
            except BrokenPipeError:
                pass
        with managed_process([sys.executable, '-I', '-B', '-c', PREVIEW_DECODER, extension], stdin=source,
                             stdout=emit, stderr=errors, preview=True) as child:
            source.close()
            emit.close()
            errors.close()
            producer = Thread(target=send, daemon=True)
            producer.start()
            deadline = time.monotonic() + 6
            while child.poll() is None:
                if time.monotonic() >= deadline:
                    raise PlatformError('Preview decoding exceeded its time limit')
                if sys.platform == 'darwin':
                    libproc = c.CDLL('/usr/lib/libproc.dylib')
                    usage = (c.c_uint64 * 12)()
                    query = libproc.proc_pid_rusage
                    query.argtypes = [c.c_int, c.c_int, c.c_void_p]
                    observed = query(child.pid, 0, c.byref(usage))
                    if child.poll() is None and (observed != 0 or max(usage[8], usage[9]) > 512 * 1024**2):
                        raise PlatformError('Preview memory enforcement failed or limit exceeded')
                try:
                    child.wait(timeout=.05)
                except subprocess.TimeoutExpired:
                    pass
            if child.returncode != 0 or output.read(8) != b'decoded':
                raise PlatformError('Preview is unreadable, exceeds bounds, or its trusted decoder is unavailable.')


def assert_process_exists(pid):
    if not _is_windows():
        os.kill(pid, 0)
        return
    api = _windows_api()
    handle = api.OpenProcess(0x100000 | 0x1000, False, int(pid))
    if not handle:
        error = c.get_last_error()
        if error == 87:
            raise ProcessLookupError(error, 'Process does not exist')
        if error == 5:
            raise PermissionError(error, 'Process identity is inaccessible')
        raise OSError(error, 'Process liveness is unknown')
    try:
        state = api.WaitForSingleObject(handle, 0)
        if state == 0:
            raise ProcessLookupError('Process has exited')
        if state != 258:
            raise OSError('Process wait state is unknown')
    finally:
        api.CloseHandle(handle)


def sync_index_modes(workspace, paths, env=None, literal=True, update_index=None):
    """Apply scoped logical modes while retaining the staged object bytes."""
    if not _is_windows() or not paths:
        return
    argv, env = git_invocation(workspace, env)
    if literal:
        argv.append('--literal-pathspecs')
    result = subprocess.run([*argv, 'ls-files', '--stage', '-z', '--', *paths],
                            capture_output=True, check=True, env=env)
    for raw in result.stdout.split(b'\0'):
        if not raw:
            continue
        header, raw_name = raw.split(b'\t', 1)
        old_mode, object_id, stage = header.decode('ascii').split()
        if stage != '0' or old_mode not in ('100644', '100755'):
            continue
        name = os.fsdecode(raw_name)
        path = Path(workspace) / name
        if not path.is_file() or not supports_mode_streams(path):
            continue
        try:
            with open(_native_path(path) + ':factory2.mode', encoding='ascii') as stream:
                mode = int(stream.read(16))
        except FileNotFoundError:
            continue
        if not 0 <= mode <= 0o777:
            raise PlatformError('Invalid logical file mode')
        new_mode = '100755' if mode & 0o111 else '100644'
        if new_mode != old_mode:
            args = ['update-index', '--cacheinfo', new_mode, object_id, name]
            if update_index:
                update_index(*args)
            else:
                subprocess.run([*argv, *args], check=True, env=env, stdout=subprocess.DEVNULL)

def supervise_git(marker, token, timeout, argv):
    """Register before launching Git, including when its original caller has died."""
    with file_lock(marker.parent / 'git-supervisor', timeout=5):
        return _supervise_git(marker, token, timeout, argv)


def _supervise_git(marker, token, timeout, argv):
    state = json.loads(read_regular(marker, marker.parent, max_bytes=16384))
    if state['token'] != token or state['state'] != 'prepared':
        raise PlatformError('Git execution intent changed.')
    def publish(**changes):
        state.update(changes)
        atomic_bytes(marker, json.dumps(state).encode())
    publish(state='starting', supervisor=os.getpid(), start=incarnation(os.getpid()))
    if not _is_windows():
        os.environ['FACTORY2_GIT_EFFECT'] = token
    with managed_process(argv, stdin=sys.stdin, stdout=sys.stdout, stderr=sys.stderr) as child:
        publish(state='running', child=child.pid, child_start=incarnation(child.pid))
        try:
            code = child.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            code = None
    if code is None:
        publish(state='timed_out', containment='windows-job-empty' if _is_windows() else 'process-group')
        return 1
    # A POSIX hook can move descendants to a different session. Group cleanup
    # and a synchronous Git return have narrower meaning than an empty Job.
    publish(state='finished' if _is_windows() else 'returned', returncode=code,
            containment='windows-job-empty' if _is_windows() else 'process-group')
    return code


def posix_effect_alive(state):
    """Positive observations only: an escaped child can change its environment."""
    group = state.get('child')
    if group:
        try:
            os.killpg(group, 0)
        except ProcessLookupError:
            pass
        else:
            return True
    tag = ('FACTORY2_GIT_EFFECT=' + state['token']).encode()
    if sys.platform == 'darwin':
        # System-protected executables may conceal their environment.
        output = subprocess.check_output(['/bin/ps', '-Eww', '-U', str(os.getuid()),
                                          '-o', 'command='], timeout=5)
        return any(tag in line.split() for line in output.splitlines())
    if sys.platform.startswith('linux'):
        for path in Path('/proc').glob('[0-9]*/environ'):
            try:
                if tag in path.read_bytes().split(b'\0'):
                    return True
            except (FileNotFoundError, PermissionError, ProcessLookupError):
                continue
    return False


if __name__ == '__main__' and sys.argv[1:2] == ['--supervise-git']:
    sys.exit(supervise_git(Path(sys.argv[2]), sys.argv[3], float(sys.argv[4]), sys.argv[5:]))
